function renderDevices(o,d){const el=$('devicesGrid');if(!el)return[];const items=allDevices(o,d).filter(x=>x.device_type==='climate');el.innerHTML=items.map(x=>`<div class="deviceCard ${x.is_outdoor?'outdoor':''}"><div class="row"><b>${roomIcon(x)} ${esc(x.device_name)}</b><span class="statusPill status-${x.status}">${x.status==='online'?'Online':x.status==='warning'?'Затримка':'Offline'}</span></div>${x.device_type==='power'?`<h3>${fmt(x.power,0)} Вт · ${fmt(x.voltage,1)} В</h3>`:`<h3>${fmt(x.temperature)}°C · ${fmt(x.humidity,0)}%</h3><small>${x.is_outdoor?'Вуличний датчик':'Кімнатний датчик'}${x.wifi_rssi!=null?' · '+x.wifi_rssi+' dBm':''}</small>`}<div class="age">Останній зв'язок: ${ageText(x.age_minutes)}</div></div>`).join('')||'<div class="empty">Пристрої не зареєстровані</div>';const rooms=items.filter(x=>x.device_type==='climate'&&!x.is_outdoor),outdoor=items.find(x=>x.is_outdoor),attention=items.filter(x=>!x.online);setHTML('roomSummary',`<div class="insight"><b>🏆 Кімнатні датчики</b><br>${rooms.filter(x=>x.online).length}/${rooms.length} online</div><div class="insight"><b>🌳 Вулиця</b><br>${outdoor?outdoor.status:'не налаштовано'}</div><div class="insight"><b>⚠ Потребують уваги</b><br>${attention.length}</div>`);setHTML('overviewRooms',`<div class="insight"><b>🏆 Найкомфортніша</b><br>${esc((o.rooms||[])[0]?.name||'—')}</div><div class="insight"><b>🌳 Вулиця</b><br>${outdoor?fmt(outdoor.temperature)+'°C · '+fmt(outdoor.humidity,0)+'%':'немає даних'}</div><div class="insight"><b>📡 Зв’язок</b><br>${state.deviceStatus?.online==null?'—':state.deviceStatus.online}/${state.deviceStatus?.total==null?'—':state.deviceStatus.total} online</div>`);renderFloorPlan();return items}function showDetail(title,html){$('detailTitle').textContent=title;$('detailBody').innerHTML=html;$('detailModal').classList.add('show')}
