function roomIcon(room){const n=String(room?.device_name||'').toLowerCase();if(room?.is_outdoor||n.includes('outdoor')||n.includes('вулиц')||n.includes('улиц'))return '🌳';if(/kids?|child|nursery|дит|детск/.test(n))return '👶';if(/hallway|corridor|hall|коридор|передпок/.test(n))return '🚪';if(/bedroom|спальн/.test(n))return '🛏️';if(/living|lounge|вітальн|гостин/.test(n))return '🛋️';if(/kitchen|кухн/.test(n))return '🍳';if(/bath|ванн/.test(n))return '🛁';if(/office|study|кабінет|кабинет/.test(n))return '💻';return '🏠'}function renderOverviewCompact(o,d,devices){const climate=devices.filter(x=>x.device_type==='climate'),outdoor=climate.find(x=>x.is_outdoor),rooms=climate.filter(x=>!x.is_outdoor),power=devices.find(x=>x.device_type==='power'),cards=[...rooms.slice(0,3),...(outdoor?[outdoor]:[])];setHTML('overviewRoomCards',cards.map((x,i)=>`<div class="compactRoom"><div class="row"><b>${roomIcon(x)} ${esc(x.device_name)}</b><span class="status-${x.status}">●</span></div><strong>${fmt(x.temperature)}°C · ${fmt(x.humidity,0)}%</strong><div class="age">${x.status} · ${ageText(x.age_minutes)}</div><div class="compactSpark"><canvas id="roomSpark${i}"></canvas></div></div>`).join('')+(power?`<div class="compactRoom"><b>⚡ ${esc(power.device_name)}</b><br><strong>${fmt(power.power,0)} Вт</strong><div class="age">${power.status} · ${ageText(power.age_minutes)}</div></div>`:''));renderRoomSparks(cards);renderHomeEnergy();const recs=o.recommendations||d.recommendations||[],alerts=d.alerts||[],offline=devices.filter(x=>!x.online),offlineNames=offline.map(x=>String(x.device_name||'').toLowerCase()),uniqueAlerts=alerts.filter(a=>{const text=String((a.alert_type||'')+' '+(a.alert_message||'')).toLowerCase();return !offlineNames.some(name=>name&&text.includes(name))}),items=[...offline.map(x=>({t:'📡 '+x.device_name,m:'Немає актуальних даних'})),...uniqueAlerts.slice(0,2).map(x=>({t:'🚨 '+(x.alert_type||'Алерт'),m:x.alert_message})),...recs.slice(0,2).map(x=>({t:'💡 '+(x.title||'Рекомендація'),m:x.message}))].slice(0,3);setHTML('homeAttention',items.map(x=>`<div class="item"><b>${esc(x.t)}</b><br><small>${esc(x.m||'')}</small></div>`).join('')||'<div class="empty">✅ Усе спокійно</div>');renderHomeWeather()}function renderRoomSparks(cards){const climate=state.homeClimate24?.datasets||state.climate?.datasets||{},keys=Object.keys(climate);(cards||[]).forEach((room,i)=>{const key=keys.find(k=>k===room.device_id||k.toLowerCase().includes(String(room.device_name||'').toLowerCase().split(' ')[0])),series=key?climate[key]:null,canvas=$('roomSpark'+i);if(!canvas||!series?.temperature?.length)return;const name='roomSpark'+i,color=room.is_outdoor?'#ffc857':'#58e1ff';state.charts[name]?.destroy();state.charts[name]=new Chart(canvas,{data:{labels:series.labels||series.temperature.map((_,n)=>n),datasets:[{label:'Температура °C',data:series.temperature,borderColor:color,backgroundColor:color+'18',type:'line',yAxisID:'y',fill:false,tension:.35,pointRadius:0,borderWidth:1.7,order:1},{label:'Вологість %',data:series.humidity,backgroundColor:color+'28',borderColor:color+'55',type:'bar',yAxisID:'y1',borderWidth:0,barPercentage:.85,categoryPercentage:1,order:2}]},options:{responsive:true,maintainAspectRatio:false,animation:false,interaction:{mode:'index',intersect:false},plugins:{legend:{display:false},tooltip:{enabled:false,external:({chart,tooltip})=>{let el=document.getElementById('roomSparkTooltip');if(!el){el=document.createElement('div');el.id='roomSparkTooltip';el.style.cssText='position:fixed;z-index:9999;pointer-events:none;padding:8px 10px;border:1px solid #58e1ff66;border-radius:9px;background:#101b30;color:#f5f8ff;font:12px Inter,system-ui,sans-serif;box-shadow:0 8px 24px #0009;white-space:nowrap;opacity:0;transition:opacity .08s';document.body.appendChild(el)}if(!tooltip||tooltip.opacity===0){el.style.opacity='0';return}el.innerHTML=`<b>${esc(tooltip.title?.[0]||'')}</b>`+tooltip.dataPoints.map(p=>`<div>${esc(p.dataset.label)}: <b>${fmt(p.raw)}</b></div>`).join('');const r=chart.canvas.getBoundingClientRect();el.style.opacity='1';el.style.left=Math.min(window.innerWidth-el.offsetWidth-8,Math.max(8,r.left+tooltip.caretX))+'px';el.style.top=Math.max(8,Math.min(window.innerHeight-el.offsetHeight-8,r.top+tooltip.caretY-el.offsetHeight-10))+'px'}}},scales:{x:{display:false},y:{display:false,min:-10,max:40},y1:{display:false,min:0,max:100}}}})})}
function renderHomeEnergy(){const canvas=$('homeEnergyChart'),empty=$('homeEnergyEmpty'),points=state.homeEnergy24?.points||[];if(!canvas)return;if(!points.length){canvas.style.display='none';if(empty)empty.hidden=false;return}canvas.style.display='block';if(empty)empty.hidden=true;dualChart('homeEnergy','homeEnergyChart',points.map(x=>friendlyTime(x.label)),[{label:'Середня потужність, Вт',data:points.map(x=>x.avg_power),borderColor:'#8c6cff',backgroundColor:'#8c6cff18',type:'line',yAxisID:'y'},{label:'Витрати за 15 хв, грн',data:points.map(x=>x.cost),borderColor:'#58e1ff55',backgroundColor:'#58e1ff55',type:'bar',yAxisID:'y1'}])}
