function scoreReasons(o,d,devices){const offline=devices.filter(x=>!x.online),alerts=d.alerts||[],reasons=[],positive=[];if(offline.length)reasons.push(`${offline.length} пристрої без актуальних даних: ${offline.map(x=>x.device_name).join(', ')}`);if(alerts.length)reasons.push(`${alerts.length} активних алертів`);if(o.scores.comfort<80)reasons.push(`Comfort ${o.scores.comfort}/100`);else positive.push(`Comfort ${o.scores.comfort}/100`);if(!offline.length)positive.push('усі пристрої передають дані');if(o.scores.energy>=80)positive.push('енергетичні показники стабільні');return{reasons,positive}}
function scoreTile(icon,title,value,details,index){return `<div class="insight scoreTile" data-score-index="${index}"><b>${icon} ${title}</b><br><strong>${value}</strong><div class="tip">${details}</div></div>`}
function renderScores(o,d,devices){const r=scoreReasons(o,d,devices),alerts=d.alerts||[],offline=devices.filter(x=>!x.online),outdoor=devices.find(x=>x.is_outdoor);const summary=[...r.reasons,...r.positive];$('scoreExplain').innerHTML=`<b>Home Score ${fmt(o.scores.overall,0)}/100 · ${o.scores.overall>=80?'Дім у доброму стані':o.scores.overall>=60?'Є фактори для покращення':'Є важливі проблеми'}</b>${summary.length?'<br>'+summary.slice(0,2).map(esc).join(' · ')+(summary.length>2?'<br>Ще '+(summary.length-2)+' фактор(и)':''):'<br>Суттєвих проблем не виявлено.'}`;const defs=[['🌡','Comfort',o.scores.comfort+'/100',`Кімнатний комфорт. ${esc(r.reasons.find(x=>x.startsWith('Comfort'))||'Температура і вологість у прийнятному діапазоні.')}`],['⚡','Energy',o.scores.energy+'/100',`Поточна потужність ${fmt(o.today.power?.power,0)} Вт, напруга ${fmt(o.today.power?.voltage,1)} В.`],['📟','Devices',(state.deviceStatus?.online==null?'—':state.deviceStatus.online)+'/'+(state.deviceStatus?.total==null?'—':state.deviceStatus.total),offline.length?`Offline: ${offline.map(x=>esc(x.device_name)).join(', ')}`:'Усі зареєстровані пристрої online.'],['🌦','Weather',o.scores.weather+'/100',`На вулиці ${fmt(outdoor?.temperature??o.today.weather?.temperature)}°C. Ризик дощу ${fmt(d.weather.daily?.[0]?.precipitation_probability,0)}%.`],['🚨','Алерти',alerts.length,alerts.length?alerts.slice(0,5).map(x=>esc(x.alert_message)).join('<br>'):'Активних алертів немає.']];$('scoreParts').innerHTML=defs.map((x,i)=>scoreTile(...x,i)).join('');$('scoreParts').onclick=e=>{const t=e.target.closest('[data-score-index]');if(t){const x=defs[+t.dataset.scoreIndex];showDetail(x[0]+' '+x[1],`<div class="item">${x[3]}</div>`)}}}
function render(){const o=state.overview,d=state.dash,s=state.score;if(!o||!d||!s)return;const status={good:['good','● Усе добре','Ваш дім під контролем'],attention:['attention','● Потребує уваги','Є події, які варто перевірити'],critical:['critical','● Критична подія','Потрібна ваша увага']}[o.status];$('statusPill').className='statusPill '+status[0];$('statusPill').textContent=status[1];$('heroTitle').textContent=status[2];$('heroText').textContent=(d.alerts?.[0]?.alert_message||o.recommendations?.[0]?.message||'Система працює стабільно.');$('score').textContent=o.scores.overall;$('scoreRing').style.setProperty('--s',o.scores.overall);const discovered=allDevices(o,d),onlineCount=state.deviceStatus?.online??null,onlineTotal=state.deviceStatus?.total??null;renderScores(o,d,discovered);const devices=discovered,onlineDevices=onlineCount;$('quickFacts').innerHTML=`<span class="fact">📟 ${onlineDevices==null||onlineTotal==null?'—':`${onlineDevices}/${onlineTotal}`} online</span><span class="fact">🚨 ${o.today.alerts} алертів</span><span class="fact">⚡ ${fmt(o.today.power?.power,0)} Вт</span><span class="fact">🌤 ${fmt(o.today.weather?.temperature)}°C</span>`;$('commandStrip').innerHTML=[commandMetric('⚡','Зараз',fmt(o.today.power?.power,0)+' Вт'),commandMetric('⚡','Сьогодні',fmt(d.insights.power.statistics.today.energy_total,2)+' кВт·год'),commandMetric('📅','Місяць',fmt(d.insights.power.statistics.month.energy_total,2)+' кВт·год'),commandMetric('💰','Витрати сьогодні',fmt(d.insights.power.statistics.today.cost_total,2)+' грн'),commandMetric('💳','Витрати місяць',fmt(d.insights.power.statistics.month.cost_total,2)+' грн')].join('');$('kpis').innerHTML=[kpi('🌡','Comfort',o.scores.comfort+'/100'),kpi('⚡','Energy',o.scores.energy+'/100'),kpi('📟','Devices',o.scores.devices+'/100'),kpi('🌦','Weather',o.scores.weather+'/100'),kpi('🚨','Алерти',o.today.alerts)].join('');$('recs').innerHTML=(o.recommendations||[]).map(x=>`<div class="item"><b>${esc(x.title)}</b><p>${esc(x.message)}</p></div>`).join('')||'<div class="item">✅ Термінових рекомендацій немає</div>';const rr=(o.rooms||[]);$('rooms').innerHTML=rr.map((x,i)=>`<div class="room"><div class="row"><b>${i===0?'🏆 ':''}${esc(x.name)}</b><span class="statusPill ${x.comfort_score>=75?'good':'attention'}">${x.comfort_score}</span></div><h3>${fmt(x.temperature)}°C · ${fmt(x.humidity,0)}%</h3><span class="roomTag">${i===0?'🏆 Найкомфортніша':'Оновлено'}</span><div class="miniTrend"></div></div>`).join('');const w=d.weather.current;$('weatherNow').textContent=`${w?.weather_icon||'🌦'} ${fmt(w?.temperature)} °C`;$('weatherInfo').textContent=w?`${w.weather_description} · ${fmt(w.humidity,0)}% · вітер ${fmt(w.wind_speed)} км/год`:'';$('forecast').innerHTML=(d.weather.daily||[]).map(x=>`<div class="forecastDay"><b>${esc(x.day_label)}</b><h2>${x.weather_icon}</h2><div>${fmt(x.temp_min)}…${fmt(x.temp_max)}°C</div><small>Дощ ${fmt(x.precipitation_probability,0)}%</small></div>`).join('');const st=d.insights.power.statistics;$('dayEnergy').textContent=fmt(st.month.energy_day,2)+' кВт·год';$('nightEnergy').textContent=fmt(st.month.energy_night,2)+' кВт·год';$('monthCost').textContent=fmt(st.month.cost_total,2)+' грн';renderDevices(o,d);renderAlertsAndRecommendations(o,d);renderOverviewCompact(o,d,devices);renderComfortMatrix(rr);renderCharts();renderEnergyExtras();renderWeather48()}
async function loadSmartRange(scope,period,from=null,to=null){const qs=new URLSearchParams({period});if(from)qs.set('from',from);if(to)qs.set('to',to);if(scope==='climate'){const hours=period==='day'?24:period==='week'?168:744;state.climate=await req('/charts/climate?hours='+Math.min(168,hours),{ttl:0});renderCharts();return}const data=await req('/charts/energy/range?'+qs.toString(),{ttl:0});state.rangeSeries[scope]=data;renderCharts()}
function setupSmartPeriods(){document.querySelectorAll('.smartPeriod').forEach(p=>p.onclick=e=>{const b=e.target.closest('[data-p]');if(!b)return;const scope=p.dataset.smartScope,period=b.dataset.p;p.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));state.smartPeriods[scope]=period;const custom=document.querySelector(`[data-custom="${scope}"]`);if(custom)custom.classList.toggle('show',period==='custom');if(period!=='custom')loadSmartRange(scope,period)});document.querySelectorAll('.customRange .apply').forEach(b=>b.onclick=()=>{const c=b.closest('.customRange'),scope=c.dataset.custom;loadSmartRange(scope,'custom',c.querySelector('.from').value,c.querySelector('.to').value)})}
function climateKey(value){return String(value||'').toLowerCase().replace(/sensor/g,'').replace(/[^a-z0-9а-яіїєґ]/g,'')}
function climateDeviceForSeries(id){const devices=(state.deviceStatus?.items||[]).filter(x=>x.device_type==='climate');const key=climateKey(id);let best=null,score=0;for(const d of devices){const did=climateKey(d.device_id),name=climateKey(d.device_name);let n=0;if(key&&did&&key===did)n=100;else if(key&&name&&key===name)n=90;else if(key&&did&&(key.startsWith(did)||did.startsWith(key)))n=Math.min(key.length,did.length);else if(key&&name&&(key.startsWith(name)||name.startsWith(key)))n=Math.min(key.length,name.length);if(n>score){score=n;best=d}}return score>=5?best:null}
function climateSeriesLabel(id,device){return device?.device_name||id}const floorPlanBindings={'1':'hallway','2':'bedroom','5':'kidsroom'},floorPlanNames={'1':'🚪 Коридор','2':'🛏️ Спальня','5':'👶 Дитяча'};
function floorPlanDevice(room){const key=floorPlanBindings[String(room)];return(state.deviceStatus?.items||[]).find(d=>d.device_type==='climate'&&(climateKey(d.device_name)===key||climateKey(d.device_id)===key||climateKey(d.device_name).startsWith(key)))||null}
function floorPlanSeries(room){const device=floorPlanDevice(room),keys=Object.keys(state.climate?.datasets||{});if(device){const match=keys.find(id=>climateDeviceForSeries(id)===device);if(match)return match}const wanted=floorPlanBindings[String(room)];return keys.find(id=>climateKey(id)===wanted)||null}
function floorPlanColor(device){if(!device)return '#94a3b8';const value=+(state.floorPlanMetric==='humidity'?device.humidity:device.temperature);if(!Number.isFinite(value))return '#94a3b8';if(state.floorPlanMetric==='humidity')return value<35?'#f59e0b':value<=60?'#34d399':value<=70?'#38bdf8':'#818cf8';return value<18?'#38bdf8':value<=25?'#34d399':value<=29?'#fbbf24':'#f87171'}
function renderFloorPlan(){const svg=$('floorPlanSvg');if(!svg)return;for(const room of ['1','2','5']){const device=floorPlanDevice(room),id=floorPlanSeries(room),poly=svg.querySelector(`[data-plan-room="${room}"]`),name=svg.querySelector(`[data-plan-name="${room}"]`),value=svg.querySelector(`[data-plan-value="${room}"]`),selected=(state.climateSelectedRooms||[]).includes(id)&&id;if(poly){poly.style.fill=floorPlanColor(device);poly.style.fillOpacity=device?.online===false?'.15':'.34';poly.classList.toggle('selected',!!selected)}if(name)name.textContent=floorPlanNames[room];if(value)value.textContent=device?`${fmt(device.temperature)}°C · ${fmt(device.humidity,0)}% · ${device.status==='online'?'Online':device.status==='warning'?'Затримка':'Offline'}`:'Датчик не знайдено'}const mode=$('climateOverlayToggle');if(mode)mode.textContent='Накладання: '+(state.climateOverlayEnabled?'увімкнено':'вимкнено');const note=$('floorPlanNote');if(note)note.textContent=state.climateOverlayEnabled?'Натискайте на кімнати, щоб додавати або прибирати серії з накладання.':'Натисніть на кімнату, щоб показати її історію; для порівняння ввімкніть накладання.'}
function selectPlanRoom(room){const id=floorPlanSeries(room);if(!id){toast('Для цієї кімнати ще немає історії температури');return}const entry=Object.entries(state.climate?.datasets||{}).find(([key])=>key===id),device=floorPlanDevice(room);if(entry&&device&&!device.online)state.climateShowArchive=true;if(state.climateOverlayEnabled){const set=new Set(state.climateSelectedRooms||[]);if(set.has(id))set.delete(id);else set.add(id);state.climateSelectedRooms=[...set];state.climatePlanRoom=set.has(id)?String(room):null}else{state.climateSelectedRooms=[id];state.climatePlanRoom=String(room)}state.climateSelectionInitialized=true;renderFloorPlan();renderCharts()}
