async function loadAll(force=false){if(state.loading||(!force&&document.visibilityState!=='visible'))return;state.loading=true;document.body.classList.add('isLoading');try{const hours=state.chartHours.power||24,base=[req('/control/overview',{ttl:force?0:60000}),req('/dashboard',{ttl:force?0:60000}),req('/home-score',{ttl:force?0:300000}),req('/devices/status',{ttl:force?0:60000})],needCharts=state.loadedTabs.has('home')||state.loadedTabs.has('energy')||state.loadedTabs.has('climate'),all=needCharts?base.concat([req('/charts/power?hours='+hours,{ttl:force?0:300000}),req('/charts/climate?hours='+(state.chartHours.climate||24),{ttl:force?0:300000}),req('/charts/energy?hours='+(state.chartHours.energy||24),{ttl:force?0:300000}),req('/charts/energy/range?period=day',{ttl:force?0:60000}),req('/charts/climate?hours=24',{ttl:force?0:60000})]):base,[o,d,s,ds,p,c,en,homeEn,homeCl]=await Promise.all(all);Object.assign(state,{overview:o,dash:d,score:s,deviceStatus:ds});if(p)state.power=p;if(c)state.climate=c;if(en)state.energySeries=en;if(homeEn)state.homeEnergy24=homeEn;if(homeCl)state.homeClimate24=homeCl;render();if(!state.rangeSeries.energy){loadSmartRange('energy','week');loadSmartRange('energy2','week')}if(!state.tariffRange)loadTariffRange();if(!state.loadedClimateWeek){state.loadedClimateWeek=true;loadSmartRange('climate','week')}$('updated').textContent='Оновлено '+new Date().toLocaleTimeString('uk-UA',{hour:'2-digit',minute:'2-digit'})}catch(e){$('updated').textContent='Помилка завантаження';toast(e.message);console.error('Dashboard load/render error',e)}finally{state.loading=false;document.body.classList.remove('isLoading')}}
async function loadTimeline(){try{const j=await req('/timeline?limit=100',{ttl:60000}),timeline=j.items||[],alerts=state.dash?.alerts||[],recs=state.dash?.recommendations||[];state.timelineItems=timeline.length?timeline:[...alerts.map(x=>({category:'alert',title:x.alert_type||'Алерт',message:x.alert_message,created_at:x.created_at,severity:x.severity})),...recs.map(x=>({category:x.category||'recommendation',title:x.title||'Рекомендація',message:x.message,created_at:x.created_at||x.generated_at||'',severity:x.priority}))].sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)));renderTimelineItems()}catch(e){toast(e.message)}}
function schedule(){clearInterval(state.timer);const ms=state.mode==='live'?60000:state.mode==='eco'?300000:0;if(ms)state.timer=setInterval(()=>loadAll(false),ms);$('mode').value=state.mode}$('mode').onchange=e=>{state.mode=e.target.value;localStorage.setItem('hmMode',state.mode);savePreference('refresh-mode',state.mode);schedule()};$('refresh').onclick=()=>loadAll(true);$('theme').onclick=()=>document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&state.mode!=='manual')loadAll(false)});
function openLogin(){$('loginModal').classList.add('show');$('password').focus()}function closeLogin(){$('loginModal').classList.remove('show')}
async function login(){try{const j=await req('/auth/login',{method:'POST',body:JSON.stringify({password:$('password').value})});state.token=j.token;sessionStorage.setItem('hmAdmin',j.token);closeLogin();$('locked').hidden=true;$('adminApp').hidden=false;loadAdmin();toast('Вхід виконано')}catch(e){$('loginError').textContent=e.message}}
async function logout(){try{await req('/auth/logout',{method:'POST'})}catch(error){console.warn('Logout request failed',error)}state.token='';sessionStorage.removeItem('hmAdmin');$('locked').hidden=false;$('adminApp').hidden=true;toast('Сесію завершено')}
async function checkSession(){if(!state.token)return;try{await req('/auth/session');$('locked').hidden=true;$('adminApp').hidden=false}catch{state.token='';sessionStorage.removeItem('hmAdmin')}}
function adminPage(x){document.querySelectorAll('.adminPage').forEach(p=>p.classList.toggle('active',p.id==='ap-'+x));if(x==='audit')loadAudit()}
async function loadAdmin(){try{const[ch,cat,set,modes,prefs]=await Promise.all([req('/admin/channels'),req('/admin/categories'),req('/admin/settings'),req('/admin/modes'),req('/admin/preferences')]);state.admin={channels:ch.channels||[],overrides:ch.overrides||[],categories:cat.categories||[]};renderChannels(state.admin.channels);renderCategories(state.admin.categories);renderSettings(set.settings);renderModes(modes.modes||[]);applyPreferences(prefs.preferences||{})}catch(e){toast(e.message)}}
function renderChannels(a){$('channelsList').innerHTML=(a||[]).map(c=>{const cats=state.admin.categories.map(k=>{const o=state.admin.overrides.find(x=>String(x.chat_id)===String(c.chat_id)&&x.category_key===k.category_key),on=o?!!o.enabled:true;return `<label class="item"><input class="toggle" type="checkbox" ${on?'checked':''} onchange="setChannelCategory('${esc(c.chat_id)}','${encodeURIComponent(k.category_key)}',this.checked)"> ${esc(k.category_key)}</label>`}).join('');return `<div class="item"><div class="row"><div><b>${esc(c.channel_name||c.chat_id)}</b><br><small>${esc(c.chat_id)}</small></div><label><input class="toggle" type="checkbox" ${c.enabled?'checked':''} onchange="patchChannel(${c.id},{enabled:this.checked?1:0})"> активний</label></div><div class="formGrid"><label class="field">Тихі години <input type="checkbox" ${c.quiet_enabled?'checked':''} onchange="patchChannel(${c.id},{quiet_enabled:this.checked?1:0})"></label><label class="field">Початок<input class="input" type="time" value="${timeValue(c.quiet_start)}" onchange="patchChannel(${c.id},{quiet_start:this.value})"></label><label class="field">Кінець<input class="input" type="time" value="${timeValue(c.quiet_end)}" onchange="patchChannel(${c.id},{quiet_end:this.value})"></label></div><details><summary>Категорії цього каналу</summary><div class="formGrid">${cats}</div></details><div class="chartTools"><button class="btn" onclick="testChannel(${c.id})">🧪 Тест</button><button class="btn danger" onclick="deleteChannel(${c.id})">Видалити</button></div></div>`}).join('')||'<div class="item">Каналів немає</div>'}
async function setChannelCategory(chat_id,k,enabled){try{await req('/admin/channel-category',{method:'PATCH',body:JSON.stringify({chat_id,category_key:decodeURIComponent(k),enabled:enabled?1:0})});toast('Маршрут каналу оновлено')}catch(e){toast(e.message)}}
async function patchChannel(id,b){try{await req('/admin/channels/'+id,{method:'PATCH',body:JSON.stringify(b)});toast('Канал оновлено');loadAdmin()}catch(e){toast(e.message)}}async function testChannel(id){try{await req('/admin/test-notification',{method:'POST',body:JSON.stringify({channel_id:id})});toast('Тест надіслано')}catch(e){toast(e.message)}}async function deleteChannel(id){if(!confirm('Видалити канал?'))return;await req('/admin/channels/'+id,{method:'DELETE'});loadAdmin()}async function addChannel(){const chat_id=prompt('Chat ID каналу, наприклад -100...');if(!chat_id)return;const channel_name=prompt('Назва каналу')||chat_id;await req('/admin/channels',{method:'POST',body:JSON.stringify({chat_id,channel_name})});loadAdmin()}
function renderCategories(a){const html=(a||[]).map(c=>`<div class="item"><div class="row"><div><b>${esc(c.category_key)}</b><br><small>${esc(c.mode||'event')}</small></div><label><input class="toggle" type="checkbox" ${c.enabled?'checked':''} onchange="patchCategory('${encodeURIComponent(c.category_key)}',{enabled:this.checked?1:0})"></label></div><div class="formGrid"><label class="field">Cooldown, хв<input class="input" type="number" value="${c.cooldown||60}" onchange="patchCategory('${encodeURIComponent(c.category_key)}',{cooldown:+this.value})"></label><label class="field">Час<input class="input" type="time" value="${timeValue(c.schedule_time)}" onchange="patchCategory('${encodeURIComponent(c.category_key)}',{schedule_time:this.value||null})"></label></div></div>`).join('');$('categoriesList').innerHTML=html;$('schedulesList').innerHTML=html}
async function patchCategory(k,b){try{await req('/admin/categories/'+k,{method:'PATCH',body:JSON.stringify(b)});toast('Категорію оновлено')}catch(e){toast(e.message)}}
function renderModes(a){$('modesList').innerHTML=(a||[]).map(m=>`<label class="item row"><span><b>${esc(m.title||m.mode_key)}</b><br><small>${esc(m.mode_key)}</small></span><input class="toggle" type="radio" name="homeMode" ${m.enabled?'checked':''} onchange="setMode('${encodeURIComponent(m.mode_key)}')"></label>`).join('')||'<div class="item">Режими не налаштовані</div>'}
async function setMode(k){try{await req('/admin/modes/'+k,{method:'PATCH',body:JSON.stringify({enabled:1})});toast('Режим дому змінено');loadAdmin()}catch(e){toast(e.message)}}
function applyPreferences(p){for(const [k,v] of Object.entries(p)){if(k.startsWith('chart-'))localStorage.setItem(k,v);if(k==='refresh-mode'){state.mode=v;schedule()}}renderCharts()}
